    # Rectangular frames are colored inward according to a central key symbol.
    # Identify all non-background single-color rectangular outlines.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    frames = []
    for color in set(v for row in grid for v in row):
        if color == bg:
            continue
