        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perim = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                 if r in (r0,r1) or c in (c0,c1)}
        if cells == perim:
            frames.append((color,r0,r1,c0,c1))
    # Small 3x3 frames encode the interior color in their center; apply same
    # color to all larger frame interiors, except the marker frames themselves.
    marker = None
    for color,r0,r1,c0,c1 in frames:
